/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let roles = event.payload.value.map(role=>role.label).join(",");
	return {
		eventName: 'SN_NS_ADMIN_INPUT_VALUE_CHANGED',
		eventPayload: {
			variableName: 'in_product_roles',
			variableValue: roles
		}
	};
}

